contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 unused) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint256 balBefore = address(this).balance;
        uint256 userBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 userAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(this).balance;

        assert(
            !reverted &&
            userBefore == 0 &&
            userAfter == 0 &&
            balAfter == balBefore
        );
    }

    receive() external payable {}
}

