pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 unused) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 balBefore = address(this).balance;
        uint256 userBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { userBefore = __r; } catch { return; }
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 userAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { userAfter = __r; } catch { return; }
        uint256 balAfter = address(this).balance;
        assertTrue(!reverted &&
            userBefore == 0 &&
            userAfter == 0 &&
            balAfter == balBefore);
    }

    function testFuzz_run(uint256 unused) public {
        _run(unused);
    }

    receive() external payable {}
}
